head.script:
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vListProcsStatCd;
scwin.TR_JOB;
scwin.mktTpCd; // 거래시장구분 1= 유가, 2=코스닥

// var gAfStdIndCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        let parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.pBzProcsNo;
        scwin.vListProcsStatCd = parentWin.scwin.vListProcsStatCd;
        scwin.mktTpCd = parentWin.scwin.mktTpCd;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        // buttonSet.setSaveInfo( btn_Save, fn_save );         // 저장
        // buttonSet.setUpdateInfo( btn_Update, fn_update );     // 수정

        // alert("vBzProcsNo :"+vBzProcsNo);
        if (scwin.vBzProcsNo !== "") {
            await scwin.readSync();
        } else {
            const sbmOptions = {
                id : "sbm_dts_Item",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_Item=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_Item.insertRow();
        }
        scwin.initForm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05106_read.onpageload" });
    }
};

/**
 * @method
